), bad_functions AS (
 SELECT signature FROM expected_functions e
 WHERE to_regprocedure(signature) IS NULL OR md5(pg_get_functiondef(to_regprocedure(signature))) IS DISTINCT FROM digest
), old_cron AS (
 SELECT value AS old FROM public.competition_policy p CROSS JOIN LATERAL jsonb_array_elements(p.legacy_snapshot->'cron') WHERE value->>'jobname'='weekly_leagues_job'
), current_cron AS (
 SELECT to_jsonb(j) AS cur FROM cron.job j WHERE j.jobname='weekly_leagues_job'
)
