   SELECT count(*)=4 AND bool_and(relrowsecurity) FROM pg_class WHERE oid IN
   ('public.exam_catalog'::regclass,'public.exam_attempts'::regclass,'public.exam_subject_results'::regclass,'public.exam_wallets'::regclass)),
 'authenticated_cannot_write_attempts',NOT has_table_privilege('authenticated','public.exam_attempts','INSERT,UPDATE,DELETE'),
 'anon_cannot_finish_ayt',NOT has_function_privilege('anon','public.finish_ayt_early(uuid)','EXECUTE'),
 'authenticated_can_edit_exam',has_function_privilege('authenticated','public.save_exam_details(uuid,jsonb,jsonb,integer)','EXECUTE'),
 'cron_expected_and_metadata_preserved',
   (SELECT count(*)=1 AND bool_and(cur->>'schedule'='1 21 * * *' AND cur->>'command'='SELECT public.process_weekly_leagues();' AND (cur->>'active')::boolean) FROM current_cron)
   AND (SELECT count(*)=1 FROM old_cron)
   AND (SELECT cur-'schedule'-'command' FROM current_cron)=(SELECT old-'schedule'-'command' FROM old_cron),
 'league_activation_utc',(SELECT activates_at FROM public.competition_policy WHERE singleton),
 'league_legacy_finalized',(SELECT legacy_finalized FROM public.competition_policy WHERE singleton),
 'profiles_count',(SELECT count(*) FROM public.profiles),
 'study_sessions_count',(SELECT count(*) FROM public.study_sessions),
 'exam_attempts_count',(SELECT count(*) FROM public.exam_attempts),
 'current_month_study_event_count',(SELECT count(*) FROM public.competition_events WHERE kind='study' AND period_month=public._competition_month(now())),
 'current_month_study_session_count',(SELECT count(*) FROM public.study_sessions WHERE completed_at>=public._competition_month_time(public._competition_month(now())) AND completed_at<public._competition_month_time((public._competition_month(now())+interval '1 month')::date))
) AS postflight;
